#import <Cocoa/Cocoa.h>
int main(){@autoreleasepool{unsigned char input[]={255,0,0,255,0,0,255,255};CGColorSpaceRef c=CGColorSpaceCreateDeviceRGB();CGContextRef src=CGBitmapContextCreate(input,1,2,8,4,c,kCGImageAlphaPremultipliedLast);CGImageRef raw=CGBitmapContextCreateImage(src);NSImage* im=[[NSImage alloc]initWithCGImage:raw size:NSMakeSize(1,2)];NSRect r=NSMakeRect(0,0,1,2);CGImageRef cg=[im CGImageForProposedRect:&r context:nil hints:nil];for(int flip=0;flip<2;flip++){unsigned char out[8]={0};CGContextRef d=CGBitmapContextCreate(out,1,2,8,4,c,kCGBitmapByteOrder32Little|kCGImageAlphaPremultipliedFirst);if(flip){CGContextTranslateCTM(d,0,2);CGContextScaleCTM(d,1,-1);}CGContextDrawImage(d,r,cg);printf("flip=%d top R=%d B=%d bottom R=%d B=%d\n",flip,out[2],out[0],out[6],out[4]);CGContextRelease(d);}CGImageRelease(raw);CGContextRelease(src);CGColorSpaceRelease(c);}return 0;}